"use client";
import React, { createContext, useContext } from "react";
import UnifyAppsAnalyticsClient from "./client";
import type { UseAnalyticsMethod } from "./types";

const Context = createContext<UnifyAppsAnalyticsClient | null>(null);

export const AnalyticsProvider = ({
  client,
  children,
}: {
  client?: UnifyAppsAnalyticsClient;
  children?: React.ReactNode;
}) => {
  if (!client) {
    return null;
  }
  return <Context.Provider value={client}>{children}</Context.Provider>;
};

export const useAnalytics = (): UseAnalyticsMethod => {
  const client = useContext(Context);
  return React.useMemo(() => {
    if (!client) {
      console.error(
        "UnifyApps client not configured!",
        "To use the useAnalytics() hook, pass an initialized UnifyApps client into the AnalyticsProvider"
      );
    }

    return {
      screen: async (...args) => client?.screen(...args),
      track: async (...args) => client?.track(...args),
      heartbeat: async (...args) => client?.heartbeat(...args),
      identify: async (...args) => client?.identify(...args),
      flush: async () => client?.flush(),
      group: async (...args) => client?.group(...args),
      alias: async (...args) => client?.alias(...args),
      reset: async (...args) => client?.reset(...args),
    };
  }, [client]);
};
